body {
  font-family: 'Segoe UI', sans-serif;
  background: #f0f4f8;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  margin: 0;
}

.container {
  background: white;
  border-radius: 12px;
  padding: 40px;
  box-shadow: 0 4px 24px rgba(0,0,0,0.1);
  text-align: center;
  max-width: 480px;
  width: 90%;
}

h1 { color: #2d3748; margin-bottom: 16px; }
p  { color: #718096; line-height: 1.6; }

button {
  background: #4299e1;
  color: white;
  border: none;
  padding: 12px 28px;
  border-radius: 8px;
  font-size: 1em;
  cursor: pointer;
  margin-top: 16px;
  transition: background 0.2s;
}

button:hover { background: #3182ce; }

#output {
  margin-top: 20px;
  font-size: 1.2em;
  color: #2d3748;
  min-height: 32px;
}

const greetings = [
  'Hello, World! 👋',
  'Bonjour le Monde! 🇫🇷',
  'Hola Mundo! 🇪🇸',
  '¡Hola! 🌍',
  'こんにちは世界！ 🇯🇵',
  'Ciao Mondo! 🇮🇹',
  'Hallo Welt! 🇩🇪',
];

let index = 0;

function greet() {
  document.getElementById('output').textContent = greetings[index % greetings.length];
  index++;
}
